//! Layer-major evaluation across objects (REQ-LAYER-001, CR 613.1, 613.5): every object of the
//! universe advances through layers 1a, 1b, 2, 3, 4, 5, 6, 7a, 7b, 7c and 7d together, so that a
//! characteristic-defining expression (CR 604.3, 613.4a) and the existence of a static effect
//! generated by another object (CR 613.8a, 611.3, 113.6) see the other objects as evaluated so
//! far.
//!
//! **Universe.** The objects of [`LayerEnvironment::objects`], sorted ascending and
//! de-duplicated, with the object asked for added, restricted to the objects whose
//! [`LayerEnvironment::base`] is `Some`. Iteration is always by ascending [`ObjectId`], never in
//! the order the environment returns them (REQ-CORE-001).
//!
//! **Per object.** Each object keeps its own scratch state, its own lock-in record (CR 613.6:
//! never shared across objects) and its own order record. Within one layer an object's steps are
//! ordered against that object's state only (CR 613.8a dependency is judged on the object under
//! evaluation); what an object reads of the others is the start-of-layer snapshot below, so the
//! result never depends on which object of the layer runs first.
//!
//! **Snapshots.** At the start of layer 7a every object's state after layers 1a-6 is frozen into
//! an [`EvaluatedView`], handed to [`LayerEnvironment::eval_value_with_view`] for each
//! non-literal power or toughness (CR 604.3, 613.4a). For the existence question of a static
//! effect whose source is another object of the universe, the source is evaluated, one level
//! deep, through the end of the effect's own layer without the effect (an effect never depends
//! on itself, CR 613.8a): from the source's start-of-layer state and lock-in record, the
//! layer's other steps for the source are applied in the REQ-LAYER-002 order, and inside that
//! run the existence of effects of yet other sources is judged on their start-of-layer state.

use std::cell::RefCell;
use std::collections::BTreeMap;

use fineprint_base::ids::{EffectId, ObjectId, Timestamp};
use fineprint_dsl::ability::Layer;
use fineprint_dsl::card::ValueExpressionAST;
use fineprint_dsl::expr::ObjectSelectorAST;

use super::error::LayerError;
use super::lockin::LockRecord;
use super::ordering::{Keyed, OrderStep, Scratch, run_layer};
use super::pipeline::{
    Evaluated, LayerEnvironment, MatchContext, ObjectBase, Step, keyword_counter_keyword,
    pt_counter_delta, start_layer_7,
};
use super::registry::{ContinuousEffects, ManaValueProvenance};

/// A read-only snapshot of every object of the evaluation's universe as evaluated so far
/// (CR 613.5), handed to [`LayerEnvironment::eval_value_with_view`].
///
/// For a characteristic-defining power or toughness (CR 604.3) the view is taken at the start of
/// layer 7a (CR 613.4a, [`EvaluatedView::layer`] is [`Layer::L7a`]): every object of the
/// universe, the evaluated object included, as it is after layers 1a-6, with its controller
/// after layer 2 (CR 613.1b) and its types, colors and abilities after layers 3-6. Power and
/// toughness in the view are as they are after layer 6 (not yet determined by layer 7): an
/// expression must not rely on another object's layer-7 values. The view is a snapshot: reading
/// it changes nothing, and its content does not depend on which object is evaluated first.
#[derive(Clone, Copy, Debug)]
pub struct EvaluatedView<'a> {
    states: &'a BTreeMap<ObjectId, Evaluated>,
    layer: Layer,
}

impl<'a> EvaluatedView<'a> {
    /// A view of `states` at `layer`.
    pub(super) fn new(states: &'a BTreeMap<ObjectId, Evaluated>, layer: Layer) -> Self {
        EvaluatedView { states, layer }
    }

    /// The object as evaluated so far, or `None` if the id is not in the universe.
    #[must_use]
    pub fn get(&self, id: ObjectId) -> Option<&Evaluated> {
        self.states.get(&id)
    }

    /// Every object of the universe, ascending [`ObjectId`].
    #[must_use]
    pub fn objects(&self) -> Vec<ObjectId> {
        self.states.keys().copied().collect()
    }

    /// The layer (sublayer) the evaluation is at when the view is handed out.
    #[must_use]
    pub fn layer(&self) -> Layer {
        self.layer
    }
}

/// The universe of an evaluation with its bases, ascending [`ObjectId`].
pub(super) type Universe = Vec<(ObjectId, ObjectBase)>;

/// The universe of an evaluation of `asked` (REQ-LAYER-001): `env.objects()` sorted and
/// de-duplicated, with `asked` added, keeping the objects that have a base.
///
/// # Errors
/// [`LayerError::UnknownObject`] if `asked` has no base.
pub(super) fn universe_for(
    env: &dyn LayerEnvironment,
    asked: ObjectId,
) -> Result<Universe, LayerError> {
    let mut ids = env.objects();
    ids.push(asked);
    ids.sort_unstable();
    ids.dedup();
    let mut out = Vec::with_capacity(ids.len());
    for id in ids {
        match env.base(id) {
            Some(base) => out.push((id, base)),
            None if id == asked => return Err(LayerError::UnknownObject(id)),
            None => {}
        }
    }
    Ok(out)
}

/// The universe of [`super::evaluate_all`]: `env.objects()` sorted and de-duplicated.
///
/// # Errors
/// [`LayerError::UnknownObject`] for the first object, ascending, without a base.
pub(super) fn universe_all(env: &dyn LayerEnvironment) -> Result<Universe, LayerError> {
    let mut ids = env.objects();
    ids.sort_unstable();
    ids.dedup();
    ids.into_iter()
        .map(|id| {
            env.base(id)
                .map(|base| (id, base))
                .ok_or(LayerError::UnknownObject(id))
        })
        .collect()
}

/// The steps of `layer` for object `id` (CR 613.7): every registered effect of the layer, except
/// `skip`, at its timestamp, and the counters of the layer at their counter timestamp
/// (CR 613.7c): keyword counters in layer 6 (CR 122.1b, 613.1f), P/T counters in layer 7c
/// (CR 122.1a, 613.4c). Unordered; [`run_layer`] orders them.
pub(super) fn layer_steps<'a>(
    effects: &'a ContinuousEffects,
    layer: Layer,
    counters: &'a BTreeMap<String, i64>,
    env: &dyn LayerEnvironment,
    id: ObjectId,
    skip: Option<EffectId>,
) -> Vec<Keyed<'a>> {
    let mut steps: Vec<Keyed<'a>> = effects
        .iter()
        .filter(|&(eid, e)| e.layer == layer && Some(eid) != skip)
        .map(|(eid, e)| (e.timestamp, Step::Effect(eid, e)))
        .collect();
    for (kind, &amount) in counters.iter().filter(|&(_, &n)| n >= 1) {
        let applies = match layer {
            // CR 122.1b, 613.1f: keyword counters in layer 6.
            Layer::L6 => keyword_counter_keyword(kind).is_some(),
            // CR 122.1a, 613.4c: P/T counters in layer 7c.
            Layer::L7c => pt_counter_delta(kind).is_some(),
            _ => false,
        };
        if applies {
            // CR 613.7c: counters apply at their counter timestamp.
            let ts = env.counter_timestamp(id, kind).unwrap_or(Timestamp::new(0));
            steps.push((ts, Step::Counter(kind.as_str(), amount)));
        }
    }
    steps
}

/// One object's evaluation in progress.
struct Slot<'e> {
    /// Whether the object is on the battlefield (CR 208.3).
    on_battlefield: bool,
    /// The object as evaluated so far.
    scratch: Scratch,
    /// The lock-in record of this object's evaluation only (CR 613.6).
    locks: LockRecord<'e>,
    /// The order of the steps used for this object (REQ-LAYER-002).
    record: Vec<OrderStep>,
}

/// The result of one board pass: per object of the universe, its state after the layers run and
/// the order record of its steps.
pub(super) type BoardResult = BTreeMap<ObjectId, (Evaluated, Vec<OrderStep>)>;

/// Evaluates every object of `universe` through `layers` (in that order, a prefix of
/// [`Layer::ALL`]), layer-major (REQ-LAYER-001, CR 613.1-613.5). See the module documentation.
pub(super) fn run_board(
    effects: &ContinuousEffects,
    env: &dyn LayerEnvironment,
    universe: Universe,
    layers: &[Layer],
) -> BoardResult {
    let counters: BTreeMap<ObjectId, BTreeMap<String, i64>> = universe
        .iter()
        .map(|(id, _)| (*id, env.counters(*id)))
        .collect();
    let mut slots: BTreeMap<ObjectId, Slot<'_>> = universe
        .into_iter()
        .map(|(id, base)| {
            // CR 613.1: start with the actual object; CR 202.3b, 202.3c, 713.5c: the base's own
            // mana-value provenance (plain by default). `pt` is `None` until layer 7 starts.
            let slot = Slot {
                on_battlefield: base.on_battlefield,
                scratch: Scratch {
                    state: Evaluated {
                        characteristics: base.characteristics,
                        controller: base.controller,
                        mana_value_provenance: env.base_mana_value_provenance(id),
                    },
                    pt: None,
                },
                // CR 613.6, 611.3a: the lock-in record of this object's evaluation only.
                locks: LockRecord::new(effects),
                record: Vec::new(),
            };
            (id, slot)
        })
        .collect();
    for &layer in layers {
        if layer == Layer::L7a {
            // CR 613.4a, 613.5, 604.3: every object after layers 1-6, frozen before any CDA
            // power or toughness is evaluated, so the order of objects never matters.
            let states: BTreeMap<ObjectId, Evaluated> = slots
                .iter()
                .map(|(id, slot)| (*id, slot.scratch.state.clone()))
                .collect();
            let view = EvaluatedView::new(&states, Layer::L7a);
            for (&id, slot) in &mut slots {
                slot.scratch.pt =
                    start_layer_7(&mut slot.scratch.state, env, id, slot.on_battlefield, &view);
            }
        }
        // CR 613.5: the start-of-layer snapshot every object reads the others from.
        let start: BTreeMap<ObjectId, (Scratch, LockRecord<'_>)> = slots
            .iter()
            .map(|(id, slot)| (*id, (slot.scratch.clone(), slot.locks.clone())))
            .collect();
        let board_env = BoardEnv {
            inner: env,
            effects,
            layer,
            counters: &counters,
            start: &start,
            memo: RefCell::new(BTreeMap::new()),
        };
        for (&id, slot) in &mut slots {
            let Slot {
                scratch,
                locks,
                record,
                ..
            } = slot;
            let steps = layer_steps(effects, layer, &counters[&id], env, id, None);
            // CR 613.2, 613.3, 613.4, 613.7, 613.8: the order within the layer or sublayer.
            run_layer(layer, steps, &board_env, id, scratch, locks, record);
        }
    }
    slots
        .into_iter()
        .map(|(id, slot)| (id, (slot.scratch.state, slot.record)))
        .collect()
}

/// The environment one layer of a board pass runs with: the caller's, except that the existence
/// of a static effect whose source is another object of the universe is asked with that
/// source's state through the end of this layer without the effect (CR 613.8a, 611.3, 113.6;
/// [`BoardEnv::foreign_view`]).
struct BoardEnv<'b, 'e> {
    /// The caller's environment.
    inner: &'b dyn LayerEnvironment,
    /// The registry being evaluated.
    effects: &'e ContinuousEffects,
    /// The layer being run.
    layer: Layer,
    /// Every object's counters.
    counters: &'b BTreeMap<ObjectId, BTreeMap<String, i64>>,
    /// Every object's state and lock-in record at the start of this layer.
    start: &'b BTreeMap<ObjectId, (Scratch, LockRecord<'e>)>,
    /// The foreign-source views computed so far, by effect: a pure function of `start`, so the
    /// memo never changes a result (REQ-CORE-001).
    memo: RefCell<BTreeMap<EffectId, Option<Evaluated>>>,
}

impl BoardEnv<'_, '_> {
    /// The source of `effect` evaluated through the end of this layer without `effect`, one
    /// level deep (CR 613.8a: an effect never depends on itself): from the source's
    /// start-of-layer state and lock-in record, the layer's other steps for the source in the
    /// REQ-LAYER-002 order, with the existence of yet other sources' effects judged on their
    /// start-of-layer state ([`NestedEnv`]). `None` when the source is not in the universe.
    fn foreign_view(&self, effect: EffectId, source: ObjectId) -> Option<Evaluated> {
        let (scratch, locks) = self.start.get(&source)?;
        let mut scratch = scratch.clone();
        let mut locks = locks.clone();
        let counters = self.counters.get(&source)?;
        let steps = layer_steps(
            self.effects,
            self.layer,
            counters,
            self.inner,
            source,
            Some(effect),
        );
        let nested = NestedEnv {
            inner: self.inner,
            start: self.start,
        };
        run_layer(
            self.layer,
            steps,
            &nested,
            source,
            &mut scratch,
            &mut locks,
            &mut Vec::new(),
        );
        Some(scratch.state)
    }
}

/// The environment of a nested source evaluation ([`BoardEnv::foreign_view`]): the caller's,
/// except that the existence of an effect whose source is yet another object is asked with that
/// object's start-of-layer state, so the evaluation is one level deep and terminates.
struct NestedEnv<'b, 'e> {
    /// The caller's environment.
    inner: &'b dyn LayerEnvironment,
    /// Every object's state and lock-in record at the start of this layer.
    start: &'b BTreeMap<ObjectId, (Scratch, LockRecord<'e>)>,
}

/// Forwards every [`LayerEnvironment`] method except `generating_ability_exists` to `inner`.
macro_rules! forward_environment {
    () => {
        fn objects(&self) -> Vec<ObjectId> {
            self.inner.objects()
        }

        fn base(&self, id: ObjectId) -> Option<ObjectBase> {
            self.inner.base(id)
        }

        fn base_mana_value_provenance(&self, id: ObjectId) -> ManaValueProvenance {
            self.inner.base_mana_value_provenance(id)
        }

        fn counters(&self, id: ObjectId) -> BTreeMap<String, i64> {
            self.inner.counters(id)
        }

        fn counter_timestamp(&self, id: ObjectId, kind: &str) -> Option<Timestamp> {
            self.inner.counter_timestamp(id, kind)
        }

        fn attached_here(&self, id: ObjectId) -> Vec<ObjectId> {
            self.inner.attached_here(id)
        }

        fn matches(&self, selector: &ObjectSelectorAST, ctx: &MatchContext<'_>) -> bool {
            self.inner.matches(selector, ctx)
        }

        fn eval_value(&self, expr: &ValueExpressionAST, object: ObjectId) -> Option<i64> {
            self.inner.eval_value(expr, object)
        }

        fn eval_value_with_view(
            &self,
            expr: &ValueExpressionAST,
            object: ObjectId,
            view: &EvaluatedView<'_>,
        ) -> Option<i64> {
            self.inner.eval_value_with_view(expr, object, view)
        }
    };
}

impl LayerEnvironment for BoardEnv<'_, '_> {
    forward_environment!();

    /// CR 613.8a, 611.3, 113.6: the object under evaluation is asked with its state so far, as
    /// given; another source of the universe with [`BoardEnv::foreign_view`].
    fn generating_ability_exists(
        &self,
        effect: EffectId,
        source: ObjectId,
        source_view: Option<&Evaluated>,
    ) -> bool {
        if source_view.is_some() {
            return self
                .inner
                .generating_ability_exists(effect, source, source_view);
        }
        let known = self.memo.borrow().contains_key(&effect);
        if !known {
            let view = self.foreign_view(effect, source);
            self.memo.borrow_mut().insert(effect, view);
        }
        let memo = self.memo.borrow();
        let view = memo.get(&effect).and_then(Option::as_ref);
        self.inner.generating_ability_exists(effect, source, view)
    }
}

impl LayerEnvironment for NestedEnv<'_, '_> {
    forward_environment!();

    /// CR 613.8a: the nested source itself with its state so far; any other source of the
    /// universe with its start-of-layer state (no further nesting).
    fn generating_ability_exists(
        &self,
        effect: EffectId,
        source: ObjectId,
        source_view: Option<&Evaluated>,
    ) -> bool {
        let view = source_view.or_else(|| self.start.get(&source).map(|(s, _)| &s.state));
        self.inner.generating_ability_exists(effect, source, view)
    }
}

/// What every forwarded [`LayerEnvironment`] method of the board's adapters ([`BoardEnv`],
/// [`NestedEnv`]) answers for `id`, `kind`, `expr` and `selector`, in a fixed order, so a unit
/// test can compare them with the caller's environment (the adapters change only the existence
/// question).
#[cfg(test)]
pub(super) fn forwarded_answers(
    env: &dyn LayerEnvironment,
    effects: &ContinuousEffects,
    id: ObjectId,
    kind: &str,
    expr: &ValueExpressionAST,
    selector: &ObjectSelectorAST,
    candidate_view: &Evaluated,
) -> Vec<String> {
    let start = BTreeMap::new();
    let counters = BTreeMap::new();
    let board_env = BoardEnv {
        inner: env,
        effects,
        layer: Layer::L1a,
        counters: &counters,
        start: &start,
        memo: RefCell::new(BTreeMap::new()),
    };
    let nested = NestedEnv {
        inner: env,
        start: &start,
    };
    let states = BTreeMap::new();
    let view = EvaluatedView::new(&states, Layer::L7a);
    let ctx = MatchContext {
        source: None,
        effect_controller: fineprint_base::ids::PlayerId::new(1),
        candidate: id,
        candidate_view,
    };
    let mut out = Vec::new();
    for e in [env, &board_env as &dyn LayerEnvironment, &nested] {
        out.push(format!(
            "{:?}|{:?}|{:?}|{:?}|{:?}|{:?}|{:?}|{:?}|{:?}",
            e.objects(),
            e.base(id),
            e.base_mana_value_provenance(id),
            e.counters(id),
            e.counter_timestamp(id, kind),
            e.attached_here(id),
            e.matches(selector, &ctx),
            e.eval_value(expr, id),
            e.eval_value_with_view(expr, id, &view),
        ));
    }
    out
}
